test_cases.assertion_pseudocode:
def approving_callback(tool_name, args):
    return True  # approval
mock_tool = lambda path: {'entries': ['a.py', 'b.py']}
mock_stream = async_iter([make_function_call_event('list_files', {'path': '.'}), make_terminal_event()])
with patch_runner(run_async=mock_stream), patch_tool('list_files', return_value={'entries': ['a.py', 'b.py']}) as mock_list:
    await collect_async(backend.execute('task', system_prompt='sys', model='gemini-2.0-flash', cwd='/workspace', permission_callback=approving_callback))
assert mock_list.was_called()
result_returned_to_model = captured_function_response.result
assert result_returned_to_model == {'entries': ['a.py', 'b.py']}

with tempfile.TemporaryDirectory() as tmp:
    cwd = Path(tmp)
    tools = make_tools(cwd)
    for tool in tools:
        if tool.__name__ in ('read_file', 'list_files'):
            result = tool(path='../../etc/passwd')
        elif tool.__name__ == 'write_file':
            result = tool(path='../../etc/evil', content='x')
        elif tool.__name__ == 'edit_file':
            result = tool(path='../../etc/passwd', old_text='root', new_text='evil')
        elif tool.__name__ == 'search_files':
            result = tool(pattern='root', path='../../etc')
        elif tool.__name__ == 'execute':
            continue  # execute does not take a path arg for containment
        assert result == {'error': 'path_not_allowed', 'detail': 'Path escapes workspace root'}

